def batch_norm2d(self, weight, bias, batch, channels, height, width,
                 eps=1e-5):
    if not isinstance(weight, Tensor):
        raise TypeError("weight must be a Tensor")
    if not isinstance(bias, Tensor):
        raise TypeError("bias must be a Tensor")
    # batch, channels, height and width must be non-bool positive ints.
    for name, value in (
        ("batch", batch),
        ("channels", channels),
        ("height", height),
        ("width", width),
    ):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(name + " must be a positive int")
        if value <= 0:
            raise ValueError(name + " must be a positive int")
    # All three operands must hold non-empty 1D finite float lists;
    # the data may have been mutated after construction, so
    # re-validate at call time.
    x_data = _require_nonempty_float_vector(self, "batch_norm2d")
    w_data = _require_nonempty_float_vector(weight, "batch_norm2d")
    b_data = _require_nonempty_float_vector(bias, "batch_norm2d")
    B, C, H, W = batch, channels, height, width
    # self stores a B x C x H x W tensor flattened in row-major
    # (n, c, r, s) order; weight and bias hold one value per channel.
    if len(x_data) != B * C * H * W:
        raise ValueError(
            "batch_norm2d input length must equal"
            " batch * channels * height * width"
        )
    if len(w_data) != C:
        raise ValueError(
            "batch_norm2d weight length must equal channels"
        )
    if len(b_data) != C:
        raise ValueError(
            "batch_norm2d bias length must equal channels"
        )
    if isinstance(eps, bool) or not isinstance(eps, float):
        raise TypeError("eps must be a positive finite float")
    if not math.isfinite(eps) or eps <= 0.0:
        raise ValueError("eps must be a positive finite float")
    # Snapshot all three operands at call time so later caller-side
    # mutation or replacement can change neither the forward result
    # nor a pending backward pass.
    x = list(x_data)
    w = list(w_data)
    b = list(b_data)
    M = B * H * W
    # Normalize each channel independently over its B*H*W positions,
    # accumulating from 0.0 in ascending (n, r, s) order:
    # mu = sum(x)/M, v = sum((x-mu)^2)/M, h = (x-mu)/sqrt(v+eps),
    # y = w[c]*h + b[c]. A non-finite intermediate aborts before a
    # result tensor exists, so no state can change on failure.
    out_data = [0.0] * (B * C * H * W)
    normalized = [0.0] * (B * C * H * W)
    denoms = []
    for c in range(C):
        total = 0.0
        for n in range(B):
            base = (n * C + c) * H * W
            for i in range(H * W):
                total += x[base + i]
                if not math.isfinite(total):
                    raise ValueError(
                        "batch_norm2d intermediate must be finite"
                    )
        mu = total / M
        if not math.isfinite(mu):
            raise ValueError(
                "batch_norm2d intermediate must be finite"
            )
        var_sum = 0.0
        for n in range(B):
            base = (n * C + c) * H * W
            for i in range(H * W):
                c_i = x[base + i] - mu
                if not math.isfinite(c_i):
                    raise ValueError(
                        "batch_norm2d intermediate must be finite"
                    )
                square = c_i * c_i
                if not math.isfinite(square):
                    raise ValueError(
                        "batch_norm2d intermediate must be finite"
                    )
                var_sum += square
                if not math.isfinite(var_sum):
                    raise ValueError(
                        "batch_norm2d intermediate must be finite"
                    )
        var = var_sum / M
        if not math.isfinite(var):
            raise ValueError(
                "batch_norm2d intermediate must be finite"
            )
        denom_sq = var + eps
        if not math.isfinite(denom_sq):
            raise ValueError(
                "batch_norm2d intermediate must be finite"
            )
        denom = math.sqrt(denom_sq)
        if not math.isfinite(denom):
            raise ValueError(
                "batch_norm2d intermediate must be finite"
            )
        for n in range(B):
            base = (n * C + c) * H * W
            for i in range(H * W):
                h_i = (x[base + i] - mu) / denom
                if not math.isfinite(h_i):
                    raise ValueError(
                        "batch_norm2d intermediate must be finite"
                    )
                normalized[base + i] = h_i
                product = w[c] * h_i
                if not math.isfinite(product):
                    raise ValueError(
                        "batch_norm2d intermediate must be finite"
                    )
                y_i = product + b[c]
                if not math.isfinite(y_i):
                    raise ValueError(
                        "batch_norm2d intermediate must be finite"
                    )
                out_data[base + i] = y_i
        denoms.append(denom)
    if not (
        self.requires_grad
        or weight.requires_grad
        or bias.requires_grad
    ):
        return Tensor._make(out_data, False, (), None)
    parent_self, parent_weight, parent_bias = self, weight, bias
    # Save w, the per-channel denominators and the normalized values
    # with the graph so a pending backward pass is independent of any
    # subsequent data mutation.
    saved_w = w
    saved_denoms = denoms
    saved_h = normalized

    def backward_fn(grad):
        # Per channel, accumulate G = sum(g) and Q = sum(g*h) from 0.0
        # in ascending (n, r, s) order, then dx =
        # w[c]/sqrt(v+eps) * (M*g - G - h*Q)/M, dw[c] = Q, db[c] = G.
        # A non-finite intermediate aborts the whole pass before any
        # grad is written.
        dx = [0.0] * (B * C * H * W)
        dw = [0.0] * C
        db = [0.0] * C
        for c in range(C):
            G = 0.0
            Q = 0.0
            for n in range(B):
                base = (n * C + c) * H * W
                for i in range(H * W):
                    G += grad[base + i]
                    if not math.isfinite(G):
                        raise ValueError(
                            "batch_norm2d backward intermediate must be"
                            " finite"
                        )
                    product = grad[base + i] * saved_h[base + i]
                    if not math.isfinite(product):
                        raise ValueError(
                            "batch_norm2d backward intermediate must be"
                            " finite"
                        )
                    Q += product
                    if not math.isfinite(Q):
                        raise ValueError(
                            "batch_norm2d backward intermediate must be"
                            " finite"
                        )
            dw[c] = Q
            db[c] = G
            scale = saved_w[c] / saved_denoms[c]
            if not math.isfinite(scale):
                raise ValueError(
                    "batch_norm2d backward intermediate must be finite"
                )
            for n in range(B):
                base = (n * C + c) * H * W
                for i in range(H * W):
                    scaled = M * grad[base + i]
                    if not math.isfinite(scaled):
                        raise ValueError(
                            "batch_norm2d backward intermediate must be"
                            " finite"
                        )
                    shifted = scaled - G
                    if not math.isfinite(shifted):
                        raise ValueError(
                            "batch_norm2d backward intermediate must be"
                            " finite"
                        )
                    correction = saved_h[base + i] * Q
                    if not math.isfinite(correction):
                        raise ValueError(
                            "batch_norm2d backward intermediate must be"
                            " finite"
                        )
                    bracket = shifted - correction
                    if not math.isfinite(bracket):
                        raise ValueError(
                            "batch_norm2d backward intermediate must be"
                            " finite"
                        )
                    product = scale * bracket
                    if not math.isfinite(product):
                        raise ValueError(
                            "batch_norm2d backward intermediate must be"
                            " finite"
                        )
                    dx_i = product / M
                    if not math.isfinite(dx_i):
                        raise ValueError(
                            "batch_norm2d backward intermediate must be"
                            " finite"
                        )
                    dx[base + i] = dx_i
        # The same object may play several roles; merge such roles
        # into one contribution per tensor, and submit only parents
        # that require grad.
        merged = {}
        roles = (
            (parent_self, dx),
            (parent_weight, dw),
            (parent_bias, db),
        )
        for parent, value in roles:
            if not parent.requires_grad:
                continue
            entry = merged.get(id(parent))
            if entry is None:
                merged[id(parent)] = [parent, value]
            else:
                combined = _merge_grad(entry[1], value)
                _ensure_finite_grad(combined)
                entry[1] = combined
        return [(entry[0], entry[1]) for entry in merged.values()]

    return Tensor._make(
        out_data,
        True,
        (parent_self, parent_weight, parent_bias),
        backward_fn,
    )

def instance_norm2d(self, batch, channels, height, width, eps=1e-5):
    # batch, channels, height and width must be non-bool positive ints.
    for name, value in (
        ("batch", batch),
        ("channels", channels),
        ("height", height),
        ("width", width),
    ):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(name + " must be a positive int")
        if value <= 0:
            raise ValueError(name + " must be a positive int")
    B, C, H, W = batch, channels, height, width
    # self stores a B x C x H x W tensor flattened in row-major
    # (n, c, r, s) order; it must be a non-empty 1D finite float list.
    data = _require_nonempty_float_vector(self, "instance_norm2d")
    length = B * C * H * W
    if len(data) != length:
        raise ValueError(
            "instance_norm2d input length must equal"
            " batch * channels * height * width"
        )
    if isinstance(eps, bool) or not isinstance(eps, float):
        raise TypeError("eps must be a positive finite float")
    if not math.isfinite(eps) or eps <= 0.0:
        raise ValueError("eps must be a positive finite float")
    # Snapshot the input at call time so later caller-side mutation or
    # replacement can change neither the forward result nor a pending
    # backward pass.
    x = list(data)
    M = H * W
    # Normalize each (n, c) instance independently over its H*W spatial
    # positions, accumulating from 0.0 in ascending (n, c, r, s)
    # order: mu = sum(x)/M, z = x - mu, v = sum(z*z)/M,
    # R = 1/sqrt(v+eps), h = z*R. A non-finite intermediate aborts
    # before a result tensor exists, so no state can change on failure.
    out_data = [0.0] * length
    centered = [0.0] * length
    scales = []
    for n in range(B):
        for c in range(C):
            base = (n * C + c) * M
            total = 0.0
            for i in range(M):
                total += x[base + i]
                if not math.isfinite(total):
                    raise ValueError(
                        "instance_norm2d intermediate must be finite"
                    )
            mu = total / M
            if not math.isfinite(mu):
                raise ValueError(
                    "instance_norm2d intermediate must be finite"
                )
            var_sum = 0.0
            for i in range(M):
                z_i = x[base + i] - mu
                if not math.isfinite(z_i):
                    raise ValueError(
                        "instance_norm2d intermediate must be finite"
                    )
                centered[base + i] = z_i
                square = z_i * z_i
                if not math.isfinite(square):
                    raise ValueError(
                        "instance_norm2d intermediate must be finite"
                    )
                var_sum += square
                if not math.isfinite(var_sum):
                    raise ValueError(
                        "instance_norm2d intermediate must be finite"
                    )
            var = var_sum / M
            if not math.isfinite(var):
                raise ValueError(
                    "instance_norm2d intermediate must be finite"
                )
            denom_sq = var + eps
            if not math.isfinite(denom_sq):
                raise ValueError(
                    "instance_norm2d intermediate must be finite"
                )
            R = 1.0 / math.sqrt(denom_sq)
            if not math.isfinite(R):
                raise ValueError(
                    "instance_norm2d intermediate must be finite"
                )
            for i in range(M):
                h_i = centered[base + i] * R
                if not math.isfinite(h_i):
                    raise ValueError(
                        "instance_norm2d intermediate must be finite"
                    )
                out_data[base + i] = h_i
            scales.append(R)
    if not self.requires_grad:
        return Tensor._make(
            out_data,
            False,
            (),
            None,
            grad_validator=lambda g: _validate_vector_grad(g, length),
        )
    parent = self
    # Save the centered values and the per-instance scales with the
    # graph so a pending backward pass is independent of any subsequent
    # data mutation.
    saved_centered = centered
    saved_scales = scales

    def backward_fn(grad):
        # Per (n, c) instance, accumulate G = sum(g) and Q = sum(g*z)
        # from 0.0 in ascending (r, s) order, then dx =
        # (R/M)*(M*g - G - z*R*R*Q) in ascending (r, s) order. Only
        # self is submitted; a non-finite intermediate aborts the
        # whole pass before any grad is written.
        dx = [0.0] * length
        for n in range(B):
            for c in range(C):
                base = (n * C + c) * M
                G = 0.0
                Q = 0.0
                for i in range(M):
                    G += grad[base + i]
                    if not math.isfinite(G):
                        raise ValueError(
                            "instance_norm2d backward intermediate must"
                            " be finite"
                        )
                    product = grad[base + i] * saved_centered[base + i]
                    if not math.isfinite(product):
                        raise ValueError(
                            "instance_norm2d backward intermediate must"
                            " be finite"
                        )
                    Q += product
                    if not math.isfinite(Q):
                        raise ValueError(
                            "instance_norm2d backward intermediate must"
                            " be finite"
                        )
                R = saved_scales[n * C + c]
                R2 = R * R
                if not math.isfinite(R2):
                    raise ValueError(
                        "instance_norm2d backward intermediate must be"
                        " finite"
                    )
                scale = R / M
                if not math.isfinite(scale):
                    raise ValueError(
                        "instance_norm2d backward intermediate must be"
                        " finite"
                    )
                for i in range(M):
                    scaled = M * grad[base + i]
                    if not math.isfinite(scaled):
                        raise ValueError(
                            "instance_norm2d backward intermediate must"
                            " be finite"
                        )
                    shifted = scaled - G
                    if not math.isfinite(shifted):
                        raise ValueError(
                            "instance_norm2d backward intermediate must"
                            " be finite"
                        )
                    correction = saved_centered[base + i] * R
                    if not math.isfinite(correction):
                        raise ValueError(
                            "instance_norm2d backward intermediate must"
                            " be finite"
                        )
                    correction = correction * R
                    if not math.isfinite(correction):
                        raise ValueError(
                            "instance_norm2d backward intermediate must"
                            " be finite"
                        )
                    correction = correction * Q
                    if not math.isfinite(correction):
                        raise ValueError(
                            "instance_norm2d backward intermediate must"
                            " be finite"
                        )
                    bracket = shifted - correction
                    if not math.isfinite(bracket):
                        raise ValueError(
                            "instance_norm2d backward intermediate must"
                            " be finite"
                        )
                    dx_i = scale * bracket
                    if not math.isfinite(dx_i):
                        raise ValueError(
                            "instance_norm2d backward intermediate must"
                            " be finite"
                        )
                    dx[base + i] = dx_i
        return [(parent, dx)]

    return Tensor._make(
        out_data,
        True,
        (parent,),
        backward_fn,
        grad_validator=lambda g: _validate_vector_grad(g, length),
    )

def gather(self, indices):
    data = _require_nonempty_float_vector(self, "gather")
    if not isinstance(indices, list):
        raise TypeError("indices must be a list of non-bool ints")
    for index in indices:
        if isinstance(index, bool) or not isinstance(index, int):
            raise TypeError("indices elements must be non-bool ints")
    if len(indices) == 0:
        raise ValueError("indices must be non-empty")
    n = len(data)
    for index in indices:
        if index < 0 or index >= n:
            raise ValueError("gather index out of range")
    # Snapshot the indices so later caller-side mutation of the list
    # cannot change what a pending backward pass will scatter.
    snapshot = list(indices)
    out_data = [data[index] for index in snapshot]
    if not self.requires_grad:
        return Tensor._make(out_data, False, (), None)
    parent = self

    def backward_fn(grad):
        dx = [0.0] * n
        for o in range(len(snapshot)):
            dx[snapshot[o]] += grad[o]
            if not math.isfinite(dx[snapshot[o]]):
                raise ValueError(
                    "gather backward intermediate must be finite"
                )
        return [(parent, dx)]

    return Tensor._make(out_data, True, (parent,), backward_fn)

def topk(self, k):
    """Return the k largest entries as (values, indices).

    Values are ordered by descending value, ties by ascending original
    index. ``values`` is a Tensor holding fresh copies of the selected
    values; ``indices`` is a brand-new list[int] of original indices.
    When self requires grad, a single-parent graph is built with private
    snapshots of the original length and the index list, so later
    mutation of self.data (or the returned indices) cannot change a
    pending backward pass.
    """
    data = _require_nonempty_float_vector(self, "topk")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be a non-bool int")
    n = len(data)
    if k < 1 or k > n:
        raise ValueError("k must satisfy 1 <= k <= len(data)")
    # Sort by descending value, then ascending original index for ties.
    # All data is finite at this point, so negation cannot produce NaN.
    order = sorted(range(n), key=lambda i: (-data[i], i))[:k]
    out_data = [data[i] for i in order]
    indices = list(order)
    if not self.requires_grad:
        out = Tensor._make(out_data, False, (), None)
        return out, indices
    parent = self
    length = n
    snapshot = list(order)

    def backward_fn(grad):
        dx = [0.0] * length
        for o in range(k):
            dx[snapshot[o]] += grad[o]
            if not math.isfinite(dx[snapshot[o]]):
                raise ValueError(
                    "topk backward intermediate must be finite"
                )
        return [(parent, dx)]

    out = Tensor._make(out_data, True, (parent,), backward_fn)
    return out, indices

